54	function groupByColumn(
55	  columns: readonly BoardColumn[],
56	  tasks: readonly BoardTask[]
57	): BoardState {
58	  const state: BoardState = {}
59	  for (const column of columns) state[column.id] = []
60	  for (const task of tasks) {
61	    state[task.columnId]?.push(task)
62	  }
63	  return state
64	}
