"use client";

import { ChevronDown, ChevronUp } from "lucide-react";

import { SheetActions } from "@/components/sheet-actions";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";

type ColumnOrderItem = {
  id: string;
  name: string;
};

export function ColumnOrderSheet({
  columns,
  onMove,
  onOpenChange,
  open,
}: {
  columns: readonly ColumnOrderItem[];
  onMove: (columnId: string, direction: "up" | "down") => void;
  onOpenChange: (open: boolean) => void;
  open: boolean;
}) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-md" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>Reorder columns</SheetTitle>
          <SheetDescription>Move each column to the position you want; the board updates instantly.</SheetDescription>
        </SheetHeader>
        <ul className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-4">
          {columns.map((column, index) => (
            <li key={column.id} className="flex items-center gap-3 rounded-lg border px-3 py-2">
              <span className="w-5 text-muted-foreground text-sm tabular-nums">{index + 1}</span>
              <span className="min-w-0 flex-1 truncate font-medium text-sm">{column.name}</span>
              <Button
                aria-label={`Move ${column.name} up`}
                disabled={index === 0}
                onClick={() => onMove(column.id, "up")}
                size="icon"
                type="button"
                variant="brand-secondary"
              >
                <ChevronUp aria-hidden="true" />
              </Button>
              <Button
                aria-label={`Move ${column.name} down`}
                disabled={index === columns.length - 1}
                onClick={() => onMove(column.id, "down")}
                size="icon"
                type="button"
                variant="brand-secondary"
              >
                <ChevronDown aria-hidden="true" />
              </Button>
            </li>
          ))}
        </ul>
        <SheetActions>
          <Button onClick={() => onOpenChange(false)} type="button" variant="brand-secondary">
            Close
          </Button>
        </SheetActions>
      </SheetContent>
    </Sheet>
  );
}

